  includeCoAuthoredBy = false;
  attribution.sessionUrl = false;
}' 2>/dev/null || nix-instantiate --eval --strict -E 'with import <nixpkgs> {}; lib.generators.toJSON {} { includeCoAuthoredBy = false; attribution.sessionUrl = false; }' 2>&1 | tail -3

