            pkgs = nixpkgs.legacyPackages.x86_64-linux;
            # qemu-vm.nix is what `nixos-rebuild build-vm` pulls in. It gives the
            # config a system.build.vm runner that boots the guest against the
            # host's /nix/store over 9p, so nothing is copied into an image. The
            # images.qemu path cannot be used here: it feeds the closure through
            # cptofs (lkl), which spins forever on a closure this size.
            vmSystem = nixpkgs.lib.nixosSystem {
              system = "x86_64-linux";
              modules = distro.devbox ++ [
                ./hosts/qemu1
                ./os/linux/virtio.nix
                "${nixpkgs}/nixos/modules/virtualisation/qemu-vm.nix"
                {
                  # qemu-vm defaults to 1 core / 1G, which will not run sway.
                  # diskSize covers only the writable root - /nix/store is the
                  # host's - so it holds /home and /var, not the 29G closure.
                  virtualisation = {
                    memorySize = 8192;
                    cores = 4;
                    diskSize = 20480;
                    graphics = true;
                    forwardPorts = [
                      {
                        from = "host";
                        host.port = 2222;
                        guest.port = 22;
                      }
                    ];
                  };
                }
