s = open(p).read()

# 1. hoist the image system into the outer let
anchor = "      wireguard = import ./config/wireguard.nix;\n"
hoist = anchor + """      # Shared by packages.devbox-qemu (the image) and apps.devbox-qemu (which
      # boots it) - the app needs config.image.filePath for the filename, which
      # lives on the NixOS config rather than on the derivation.
      devboxQemuImage = nixpkgs.lib.nixosSystem {
        system = "x86_64-linux";
        modules = distro.devbox ++ [
          ./os/linux/virtio.nix
          ./os/linux/repart-image.nix
        ];
        specialArgs = { inherit sops-nix; };
      };
"""
assert s.count(anchor) == 1, f"let anchor={s.count(anchor)}"
s = s.replace(anchor, hoist)

# 2. package now just references it
old_pkg = """          devbox-qemu =
            let
              config = nixpkgs.lib.nixosSystem {
                system = "x86_64-linux";
                modules = distro.devbox ++ [
                  ./os/linux/virtio.nix
                  ./os/linux/repart-image.nix
                ];
                specialArgs = { inherit sops-nix; };
              };
            in
            config.config.system.build.image;"""
assert s.count(old_pkg) == 1, f"pkg anchor={s.count(old_pkg)}"
s = s.replace(old_pkg, "          devbox-qemu = devboxQemuImage.config.system.build.image;")

# 3. app uses config.image.filePath instead of passthru.filePath
old_ref = "${image}/${image.passthru.filePath}"
assert s.count(old_ref) == 1, f"ref anchor={s.count(old_ref)}"
s = s.replace(old_ref, "${image}/${devboxQemuImage.config.image.filePath}")
open(p, "w").write(s)
print("patched")
