# aerc, reading mail from mail.hgeorgiev.com.
#
# Passwords come from secrets/mailboxes.enc.json via sops-nix (see
# ../sops), which decrypts them to files under ~/.config/aerc. aerc reads
# those with source-cred-cmd / outgoing-cred-cmd rather than having them
# inlined, so accounts.conf itself holds no credentials - which matters
# because home-manager writes it into the world-readable Nix store.
{ config, ... }:
let
  imapHost = "mail.hgeorgiev.com:993";
  smtpHost = "mail.hgeorgiev.com:465";

  # dovecot has ssl=required and postfix exposes submissions on 465 with
  # implicit TLS, so both ends are imaps/smtps rather than STARTTLS.
  account = address: passwordFile: {
    from = address;
    source = "imaps://${address}@${imapHost}";
    source-cred-cmd = "cat ${passwordFile}";
    outgoing = "smtps://${address}@${smtpHost}";
    outgoing-cred-cmd = "cat ${passwordFile}";
    default = "INBOX";
    copy-to = "Sent";
    cache-headers = true;
  };
in
{
  imports = [ ../sops ];

  programs.aerc = {
    enable = true;

    extraAccounts = {
      "me@hgeorgiev.com" = account "me@hgeorgiev.com" config.sops.secrets.mail_me_hgeorgiev.path;
      "contacts@dissona.app" =
        account "contacts@dissona.app"
          config.sops.secrets.mail_contacts_dissona.path;
    };

    extraConfig = {
      general.unsafe-accounts-conf = false;
      ui = {
        threading-enabled = true;
        sort = "-r date";
create-msg-store-on-startup = true;
      };
      viewer.alternatives = "text/plain,text/html";
    };
  };
}

