python3 - <<'PY'
p = "home-manager/aerc/default.nix"
s = open(p).read()
old = """  account = address: passwordFile: {
    from = address;
    source = "imaps://${address}@${imapHost}";
    source-cred-cmd = "cat ${passwordFile}";
    outgoing = "smtps://${address}@${smtpHost}";
    outgoing-cred-cmd = "cat ${passwordFile}";"""
new = """  # The username is the full address, so its @ has to be percent-encoded:
  # aerc parses these with Go's net/url, whose validUserinfo rejects a bare @
  # in the userinfo with "invalid userinfo".
  account =
    address: passwordFile:
    let
      user = builtins.replaceStrings [ "@" ] [ "%40" ] address;
    in
    {
      from = address;
      source = "imaps://${user}@${imapHost}";
      source-cred-cmd = "cat ${passwordFile}";
      outgoing = "smtps://${user}@${smtpHost}";
      outgoing-cred-cmd = "cat ${passwordFile}";"""
assert s.count(old) == 1, f"anchor={s.count(old)}"
s = s.replace(old, new)
old2 = """    default = "INBOX";
    copy-to = "Sent";
    cache-headers = true;
  };
in"""
new2 = """      default = "INBOX";
      # dovecot's inbox namespace has no prefix and separator "/", with a
      # Sent mailbox flagged \\\\Sent - so this is the plain name.
      copy-to = "Sent";
      cache-headers = true;
    };
in"""
assert s.count(old2) == 1, f"anchor2={s.count(old2)}"
open(p, "w").write(s.replace(old2, new2))
print("patched")
PY
