python3 - <<'PY'
p = "hosts/lucie/observability.nix"
s = open(p).read()

s = s.replace("{ lib, ... }:", "{ config, lib, ... }:", 1)

old = """  services.grafana = {
    enable = true;

    settings.server = {
      http_addr = "0.0.0.0";
      http_port = grafanaPort;
    };"""
new = """  # Grafana encrypts datasource credentials in its DB with this. NixOS 26.05
  # dropped the built-in default, so it has to be supplied; $__file{} keeps it
  # out of the world-readable store copy of grafana.ini.
  sops.secrets.grafana_secret_key = {
    sopsFile = ../../secrets/grafana.enc.json;
    format = "json";
    key = "secret_key";
    owner = "grafana";
    mode = "0400";
  };

  services.grafana = {
    enable = true;

    settings = {
      server = {
        http_addr = "0.0.0.0";
        http_port = grafanaPort;
      };

      security.secret_key = "$__file{${config.sops.secrets.grafana_secret_key.path}}";
    };"""
assert s.count(old) == 1, f"anchor={s.count(old)}"
s = s.replace(old, new)
open(p, "w").write(s)
print("patched")
PY
nix fmt >/dev/null 2>&1
sed -n '54,75p' hosts/lucie/observability.nix

